import pathlib,json,hashlib,platform,subprocess
root=pathlib.Path.cwd();r=root/'.workspace/research/doubao-alignment'
def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()
files=list((root/'.workspace/ablation-models/qwen3-1.7b').iterdir())+list((root/'apps/desktop/resources/darwin-arm64/llm').glob('*.dylib'))
sources=['packages/core/domain/speech_cleanup.go','packages/core/domain/rewrite.go','packages/core/domain/rewrite_fidelity.go','packages/core/domain/correction.go','packages/core/application/live.go','apps/desktop/infrastructure/llm/engine/engine.go','apps/desktop/cmd/arion-rewrite-bench/main.go','apps/desktop/cmd/arion-llm/main.go','apps/desktop/infrastructure/llm/client/client.go','apps/desktop/infrastructure/llm/protocol/protocol.go','tools/evaluation/live/score-text.mjs','tools/evaluation/diagnostic/metrics.mjs']
frozen=json.loads((r/'frozen.json').read_text()); assert sha(r/'heldout.json')==frozen[str(r.relative_to(root)/'heldout.json')]
manifest={'schema':'arion-disfluency-diagnostic-v1','status':'frozen-before-heldout','revision':subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),'dirty':True,'host':{'os':subprocess.check_output(['sw_vers','-productVersion'],text=True).strip(),'cpu':subprocess.check_output(['sysctl','-n','machdep.cpu.brand_string'],text=True).strip(),'goArch':subprocess.check_output(['go','env','GOARCH'],text=True).strip(),'power':subprocess.check_output(['pmset','-g','batt'],text=True).strip(),'ram':int(subprocess.check_output(['sysctl','-n','hw.memsize'],text=True))},'settings':{'threads':4,'prompt':'live-v2','cleanup':'speech-spans-v1','greedy':True,'thinking':False,'maxLength':4096,'maxNewTokens':384,'correct':True,'livePrefixes':True,'context':False,'schedule':'sequential baseline then candidate per set','cold':'load reported separately; warm model for requests','notes':'Other desktop processes and a separate phonetic benchmark were active; latency is descriptive, not an isolated speed comparison.'},'artifacts':{str(p.relative_to(root)):sha(p) for p in files if p.is_file()},'sources':{p:sha(root/p) for p in sources},'binaries':{p.name:sha(p) for p in r.glob('*') if p.name in ['baseline-worker','baseline-bench','final-worker','final-bench','baseline-audio','final-audio']},'corpora':{str(p.relative_to(root)):sha(p) for p in [r/'heldout.json',r/'audio-corpus.json',root/'.workspace/research/multilingual-disfluency/corpus.json',root/'.workspace/research/rewrite-alignment/corpus.json',root/'.workspace/live-heldout-corpus.json']}}
prior=json.loads((r/'adopted-manifest.json').read_text())
assert manifest['artifacts']==prior['artifacts'], 'model/runtime artifacts changed'
manifest['asrFiles']={str(p.relative_to(root)):sha(p) for p in (root/'.workspace/models/store').rglob('*') if p.is_file()}
manifest['asrCatalogSha256']=sha(root/'models/catalog.json')
manifest['audioManifestSha256']=sha(r/'audio-fixtures/manifest.json')
manifest['scorers']={str(p.relative_to(root)):sha(p) for p in [root/'tools/evaluation/live/report.mjs',root/'tools/evaluation/live/score-text.mjs',root/'tools/evaluation/live/score-audio.mjs',root/'tools/evaluation/diagnostic/metrics.mjs']}
with (r/'final-manifest.json').open('x') as f:f.write(json.dumps(manifest,indent=2)+'\n')
